options(stringsAsFactors=FALSE,warn=1)
project<-normalizePath(getwd(),winslash="/",mustWork=TRUE);if(basename(project)!="longitudinal_upgrade")stop("Run from project root")
od<-file.path(project,"results","causal");ld<-file.path(project,"logs","causal");dir.create(od,FALSE,TRUE)
writeLines(capture.output(sessionInfo()),file.path(od,"sessionInfo.txt"),useBytes=TRUE)
status<-data.frame(status="CAUSAL ANALYSIS NOT IDENTIFIABLE / UNSTABLE",exact_reason="Measured time-varying covariates remained materially imbalanced across treatment waves after multinomial stabilized IPTW, longitudinal CBPS-IPW, generalized overlap weighting and Super Learner-IPTW. A five-imputation, wave-specific MICE reanalysis also failed balance (worst maximum absolute SMD 0.690 for multinomial IPTW and 0.843 for overlap weighting) despite adequate post-truncation ESS. Generalized overlap additionally collapsed the complete-data joint longitudinal support population. No failed weighting approach was allowed to enter an outcome model.")
write.csv(status,file.path(od,"final_causal_status.csv"),row.names=FALSE)
files<-list.files(c(file.path(project,"causal","scripts"),file.path(project,"results","causal"),file.path(project,"tables","causal"),file.path(project,"figures","causal")),recursive=TRUE,full.names=TRUE)
files<-files[file.info(files)$isdir%in%FALSE];manifest<-data.frame(file=substring(normalizePath(files,winslash="/"),nchar(project)+2),bytes=file.info(files)$size,md5=unname(tools::md5sum(files)))
write.csv(manifest,file.path(od,"causal_manifest_md5.csv"),row.names=FALSE)
writeLines("CAUSAL_EXPORT=PASS; FINAL STATUS=NOT IDENTIFIABLE / UNSTABLE",file.path(ld,"09_causal_export_results.log"),useBytes=TRUE)
